insert into public.main_guides(name, body, checklist) values
('교통·도로', '도로와 교통시설의 위치, 현재 상태, 통행에 미치는 영향을 정리해 주세요.', array['정확한 위치 또는 주변 건물','안전한 곳에서 촬영한 현장 사진','발견한 날짜와 통행에 미치는 영향']),
('환경', '불편이 발생한 위치와 범위, 반복되는 시간대를 정리해 주세요.', array['발생 위치와 오염 범위','발견한 날짜와 반복 여부','현장 상태를 확인할 수 있는 사진']),
('공공시설', '시설의 종류와 위치, 어떤 부분이 작동하지 않거나 파손되었는지 정리해 주세요.', array['시설 이름과 위치','고장 또는 파손 상태','시설 관리번호가 보이면 함께 기록']),
('생활', '불편의 내용과 발생 시간, 반복되는 정도를 구체적으로 정리해 주세요.', array['발생 장소와 날짜','발생 시간대와 지속 시간','생활에 미치는 영향'])
